/*
 * EVERYTHING HELD ABOUT THE SIGNED-IN PERSON, AS ONE DOCUMENT (TASK-L185 §3).
 *
 * The rows come from `shared/Rows about` — the one plan deletion also reads —
 * and the account from `_User` by the session's id. A staff account has no
 * learner, so its document is the account alone.
 *
 * Left out, and the document's own readme says so, because a file that opens
 * "everything" with a quiet gap is a technicality rather than an answer:
 *   - a coach's INTERNAL notes (the product's L128): written for the coach's own
 *     use; whether they could be withheld from a formal subject-access request
 *     is a legal question this file does not answer;
 *   - session and sign-in-link TOKENS: only when each was made is included,
 *     because the token itself would be a key to the account;
 *   - a group's own brief or session: it belongs to the group. Their answers
 *     to a group's brief ARE included;
 *   - the coach's private note about them (`LearnerInvite.label`, TASK-L184):
 *     the trainer's shorthand is the trainer's data (the product's L84, whose
 *     export withholds it). The invite itself, and when they were added, are here.
 *
 * Nothing here is written: an export changes no row.
 */
if (Inputs.userId !== undefined && Inputs.rows !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      if (!userId) throw new Error('no account');
      const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
      const users = await q('_User', { objectId: { equalTo: userId } });
      if (users.length !== 1) throw new Error(users.length ? 'two accounts for one id' : 'no account');
      const u = users[0];
      const sessions = await q('_Session', { userId: { equalTo: userId } });
      const current = Noodl.Users.Current;
      const roles = current && current.Properties && typeof current.Properties.get === 'function'
        ? current.Properties.get('roles') || []
        : [];

      const DROP = new Set(['ACL', 'sessionToken', '_hashed_password', 'password', 'authData']);
      const clean = (r) => {
        const out = {};
        for (const k of Object.keys(r)) if (!DROP.has(k)) out[k] = r[k];
        return out;
      };

      const rows = Inputs.rows || {};
      const collections = {};
      let internalNotes = 0;
      for (const c of Object.keys(rows)) {
        let list = rows[c] || [];
        if (c === 'LearnerInvite') {
          list = list.map((r) => { const o = Object.assign({}, r); delete o.label; delete o.createdByEmail; return o; });
        }
        if (c === 'LessonDraft') {
          // Which other learner a draft was copied from is about somebody else, and
          // who last saved it is the coach's address (TASK-L189 §5; the product's L84).
          list = list.map((r) => { const o = Object.assign({}, r); delete o.copiedFromLearnerId; delete o.updatedByEmail; return o; });
        }
        if (c === 'CoachNote') {
          internalNotes = list.filter((n) => n.visibility === 'internal').length;
          list = list.filter((n) => n.visibility !== 'internal');
        }
        collections[c] = list.map(clean);
      }

      const doc = {
        readme: [
          'Everything Digital Bricks Training holds about you, as of ' + new Date().toISOString() + '.',
          'It leaves out five things, on purpose. Notes your coach marked as for their own use only' +
            (internalNotes ? ' (' + internalNotes + ' of them)' : ' (there are none)') +
            '. The private note your coach keeps to tell people apart, which is theirs. The session and sign-in-link tokens themselves, because each is a key to your account: only when each was made is here. ' +
            "A group's own brief or meeting, which belongs to the group; your answers to a group's brief are here. " +
            'And, on a draft of a lesson for you, which other learner it was copied from and the address of whoever last saved it: the first is about somebody else, the second is your coach\'s.',
          'If you think something is missing, write to the address in the privacy notice.'
        ],
        account: {
          email: u.email || null,
          firstName: u.firstName || null,
          lastName: u.lastName || null,
          roles: roles,
          createdAt: u.createdAt || null,
          privacyVersion: u.privacyVersion || null,
          privacyAcceptedAt: u.privacyAcceptedAt || null,
          sessions: sessions.map((s) => ({ createdAt: s.createdAt || null }))
        },
        collections: collections
      };
      Outputs.document = doc;
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      console.error('[dbt:exportMine] refused: ' + Outputs.error + ' user=' + String(Inputs.userId || '-'));
      Outputs.failed();
    }
  })();
}
